import json,pathlib,sys,re
sys.path.insert(0,str(pathlib.Path(__file__).parent))
# Do not import author.py: refreshing question data must not silently repin chapters.
import hashlib
R=pathlib.Path(__file__).resolve().parents[1]; files={f['path']:f for f in json.loads((R/'content/snapshot.json').read_text())}
def ref(path,needle=None,count=18):
 ls=files[path]['text'].split('\n'); s=next((i for i,l in enumerate(ls) if needle and needle in l),0); e=min(s+count,len(ls));return {'path':path,'start':s+1,'end':e,'hash':hashlib.sha256('\n'.join(ls[s:e]).encode()).hexdigest()}
# Each tuple is a distinct question with an authored short answer and follow-up.
groups={
'start-here':('src/lib/plans.ts',[
('What does Mailloop do?','It helps job seekers send personalized cold emails through their own Gmail.','Contacts and templates become individual per-recipient messages; sending, usage and billing state are durable.'),
('What are the current campaign limits?','Free: 3 recipients. Premium: 10 recipients.','With gating enabled, daily caps are 3/20 and allowances are 15/300. Remaining reservations can reduce available capacity.'),
('What happens to a 15-recipient request?','campaignSchema rejects it before plan enforcement.','Its maximum is the Premium campaign limit of 10. A four-recipient Free request instead reaches the plan-specific check.'),
('Is PAID a third product plan?','No. PAID is the internal enum for Premium.','PLAN_LABELS maps the enum to public copy. Use this distinction when reading database records and UI text.')]),
'architecture':('src/lib/actions.ts',[
('Where does durable truth live?','PostgreSQL stores campaigns, sends, usage and recovery state.','Inngest events trigger work, but committed queue rows are the durable intent when publication fails.'),
('Why not send all mail inside a server action?','The implementation commits durable work and dispatches background events.','This allows recovery after UI navigation or publication interruption; it adds orchestration and reconciliation complexity.'),
('What is the outbox pattern here?','Commit the queued intent before publishing an event.','submitCampaign catches dispatch failure; later reconciliation repairs publication without replacing the delivery identity.'),
('Does package presence explain architectural motivation?','No. It establishes implementation use.','Label a reason CONFIRMED only when a comment or decision document actually states it; otherwise use INFERRED.')]),
'database':('prisma/schema.prisma',[
('Why snapshot recipient and template fields on Send?','The queued message retains the approved values.','Editing a contact or template later does not rewrite the campaign snapshot. This also creates explicit content-retention duties.'),
('What prevents duplicate campaign creation?','An owner-scoped idempotency key and a unique constraint.','The owner transaction first checks for a previous campaign. Replays return its identity rather than inserting another.'),
('Why separate reservations from Send rows?','Accounting must survive history deletion.','UsageReservation has a stable delivery key and nullable Send link with SetNull behavior, while period evidence remains durable.'),
('Why does AccountDeletionJob lack a User foreign key?','Recovery must outlive removal of User content.','The job retains cleanup markers, deadlines, provider identities and bounded credentials independently.'),
('What is a composite ownership constraint?','A relation that includes tenant identity as part of its key.','Reservation period references use period ID plus userId, preventing cross-owner period association at the schema level.'),
('Is deleting history the same as deleting an account?','No. History removal preserves safeguards and accounting.','Receipts and delivery identities may remain after history deletion; account deletion has a separate recovery lifecycle.')]),
'authentication':('src/auth.ts',[
('Which session strategy is configured?','JWT sessions.','auth.ts configures strategy jwt and manually persists User rows in callbacks; it does not configure a Prisma adapter.'),
('Why is verified email alone insufficient for automatic linking?','The app must not silently join unrelated existing accounts.','The jwt callback resolves by Google subject and rejects an email owner whose ID differs from that identity.'),
('Does login imply Gmail sending permission?','No. Scope and a usable refresh credential are checked separately.','gmailAuthorized combines granted gmail.send permission with refresh-token availability, and send policy checks fresh state.'),
('Where is the refresh token stored?','Encrypted server-side on User, with bounded retention on deletion jobs.','The v2 envelope binds owner identity using authenticated encryption; plaintext is not projected into the session.'),
('What happens when Google omits a new refresh token?','An existing encrypted credential can be retained.','The callback updates encryptedRefreshToken only when account.refresh_token is present, while computing authorization from new scope evidence.'),
('How does account deletion affect existing sessions?','The session callback removes a usable owner ID for missing or deletion-pending users.','requireUser also queries current owner state; a still-present browser cookie does not restore account availability.')]),
'sending':('src/lib/inngest.ts',[
('What are the delivery states?','READY, ATTEMPTING, UNCERTAIN and DONE.','They complement the user-facing SendStatus. FAILED can coexist with UNCERTAIN and does not necessarily prove non-delivery.'),
('When is network preparation performed?','After preflight and before the final database claim, outside owner locks.','The worker prepares token, PDF bytes and MIME, then rechecks controls and usage at one fresh authorization time.'),
('Why recheck after MIME preparation?','Policy or quota boundaries may change while preparation is slow.','Suspension, pauses, period transitions and other owner activity can invalidate earlier permission; the final claim uses current state.'),
('Can a timeout mean the email was sent?','Yes. A lost response does not prove rejection.','The worker records uncertainty and retains usage rather than authorizing a duplicate submission.'),
('Are Gmail requests automatically retried?','The current email worker disables automatic retries and the send call sets retry false.','Pacing waits and publication repair occur before an attempt; they are different from repeating an ambiguous submission.'),
('Does Message-ID guarantee provider deduplication?','No. It is a stable identity in the message, not a Gmail acceptance guarantee.','Local uniqueness, state checks and claims prevent many duplicates, but the provider/database boundary remains non-atomic.'),
('How does the app avoid CC/BCC batching?','buildMime constructs one To recipient for each Send.','There is no CC/BCC population in the shown composer. Each recipient gets a separate rendered message.'),
('Which template placeholders are supported?','{{name}}, {{company}} and {{role}}.','Validation rejects unsupported or malformed tokens; campaign creation rechecks the rendered subject for newlines.'),
('What happens after a definite provider rejection?','The appropriate reservation is released and the send finishes without automatic resubmission.','Credential or throttle failures may pause other queued work; a definite rejection is not the same as an unknown send-time outcome.'),
('What does normal pacing mean?','Sends are normally spaced about five seconds apart.','Provider waits, preparation and orchestration add delay. The constant is not a measured end-to-end throughput claim.')]),
'inngest':('src/app/api/inngest/route.ts',[
('How many Inngest functions are registered?','Eight in the source endpoint.','They cover sending, quota reconciliation, attachment discovery/cleanup, deletion sweep/worker, billing maintenance and rate-limit cleanup.'),
('How is per-user delivery concurrency limited?','sendEmail uses concurrency limit 1 keyed by event.data.userId.','Database claims are still needed because orchestration configuration alone cannot provide atomic provider acceptance.'),
('What does hourly reconciliation repair?','Accounting evidence, abandoned claims and interrupted publication.','It must not turn an uncertain delivery into a fresh send. Deferred work is republished only when eligible.'),
('Why is billing maintenance every four hours?','The source comment explicitly cites the Inngest Free execution allowance.','This is confirmed decision evidence. Its recovery delay is a consequence, while actual provider pricing/capacity remains external.')]),
'payments':('src/lib/billing/config.ts',[
('Does this snapshot support live billing?','Yes, with an explicit live_mode configuration and rollout guards.','Older test-only guidance is stale. This says nothing about whether a deployed account has live checkout enabled.'),
('Can switching environment variables convert test customers into live ones?','No. The database binds to one Dodo environment and business.','A mismatch fails closed; existing unbound provider data requires review. Product/customer/session identities do not cross modes.'),
('Does a checkout return URL prove payment?','No. Access requires verified provider evidence.','The return page displays state; signed events and server-side reconciliation maintain subscription observations.'),
('What is verified by Standard Webhooks?','The exact raw body against the signature headers and timestamp tolerance.','Verification precedes normalization/storage. Reserializing parsed JSON before verification would change the signed bytes.'),
('How are duplicate billing callbacks handled?','A unique webhook ID and stored payload hash.','Identical redelivery retains the first receipt; a different payload using the same ID raises a conflict.'),
('Why commit the receipt before processing?','A processing interruption remains recoverable.','after() attempts processing, while scheduled recovery can find committed RECEIVED/RETRY receipts later.'),
('How can paid access remain after cancellation?','Verified cancellation at period end can preserve access until the deadline.','Entitlement resolution uses lifecycle status and half-open period boundaries rather than simply testing a CANCELLED string.'),
('What is grace-period usage?','An extension of the same allowance operational end.','It must not create a second monthly allowance. Unresolved active provider boundaries pause sending rather than inventing dates.')]),
'frontend':('src/components/compose.tsx',[
('Where are plan restrictions enforced?','Server actions, policy helpers and final worker checks.','Client feature locks and allowance cards explain restrictions but cannot authorize a stale request.'),
('What does a progress timer prove?','It presents an estimate or state projection, not provider delivery.','Read committed send state and the provider evidence path; browser timing cannot determine acceptance.'),
('How do page and component files divide work?','Server pages prepare data; focused client components handle interactions.','Trace Compose through its page, component, submit action and business function to follow both rendering and mutation.')]),
'security-reliability':('src/lib/crypto.ts',[
('What binds v2 credentials to the owner?','AES-GCM additional authenticated data includes the owner UUID.','The envelope also authenticates version, key ID and Gmail credential purpose; moving ciphertext to another owner fails.'),
('How does rotation avoid overwriting reconnect credentials?','It updates only when the old ciphertext still matches.','Compare-and-swap conditions include current deletion/expiry state. A concurrent reconnect or erasure wins.'),
('Can old keys be removed immediately after rotation?','Not safely without checking retained credentials and backups.','A restored backup may still hold v1 or older v2 envelopes. Repository instructions call for a restore/decrypt exercise.'),
('Are PDF magic-byte checks malware scanning?','No. They check size, type and a PDF prefix.','Treat harmful document content as a possible risk; do not claim the shown validation proves harmlessness.'),
('What does fail closed mean here?','Unavailable controls or limiting infrastructure block protected operations.','A missing SystemControl row or limiter error must not silently grant sending or expensive requests.'),
('Are automatic operator alerts present?','The documented alert delivery/monitoring jobs were removed.','Safe logs and persisted recovery remain. An external operational process must observe them; production monitoring is unknown.'),
('Does reconnecting Gmail reset usage?','No. It can clear credential/domain-policy pause state.','It does not erase app accounting, remove suspension or revive cancelled work.')]),
'scaling':('src/lib/usage-ledger.ts',[
('What would you measure before scaling workers?','Queue age, publication delay, lock waits, provider latency and uncertainty rate.','Per-owner serialization and provider limits are distinct constraints. A global worker increase may not improve one owner’s throughput.'),
('Why not replace reservations with count-then-send?','Concurrent requests can each see capacity and over-admit.','The owner transaction reserves the full batch and coordinates claim/settlement with durable identities.'),
('What is the risk of removing owner locks?','Quota, cancellation and claim decisions can race.','A replacement needs proven concurrency invariants, not just a higher parallelism setting.'),
('Can the repository prove production capacity?','No. It provides constraints and test scenarios, not production measurements.','Use disposable data and fake providers to measure representative workloads, then verify provider quotas separately.')]),
'function-reference':('src/lib/session.ts',[
('Are all caller links exact?','No. Static call candidates are navigation evidence with explicit limits.','Framework invocation, JSX references, aliases and dynamic properties can evade or confuse name-based caller matching.'),
('What should a function explanation include?','Inputs, result, side effects, callers and failure behavior.','Follow the exact source contract. Pure helpers, internal database primitives and authenticated actions have different assumptions.')]),
'walkthrough-deletion':('src/lib/account.ts',[
('Why disable normal credentials before cleanup completes?','Deletion immediately makes the account unavailable while recovery continues independently.','The deletion job retains only deadline-limited revocation material and tracks incomplete external work.'),
('What if billing cancellation fails during deletion?','The durable deletion workflow retains unfinished billing recovery.','It should not falsely mark completion or depend on an already-deleted User relation.')]),
'walkthrough-attachment':('src/lib/storage.ts',[
('Why retain an obsolete PDF for an uncertain send?','The unresolved campaign can still depend on that selected attachment.','Cleanup protects current and queued/attempting/uncertain references; replacement is not permission to delete every previous file.'),
('Why have both deletedAt and storageDeletedAt?','Logical retirement and physical deletion can fail independently.','The remaining pending marker allows a later cleanup pass to retry external storage deletion without losing metadata.')])}
questions=[]
for chapter,(path,rows) in groups.items():
 for q,a,d in rows:questions.append({'id':f'q{len(questions)+1:02}','question':q,'short':a,'deep':d,'chapter':chapter,'ref':ref(path)})
(R/'content/questions.json').write_text(json.dumps(questions,indent=2))
defs=[
('OAuth','Delegated authorization: Google grants this app selected permissions without sharing the user password.','authentication'),('JWT','A token-based session representation managed by Auth.js; this app puts owner identity in its callbacks.','authentication'),('session','The authenticated application identity; distinct from the refresh credential needed to send Gmail.','authentication'),('refresh token','A server-held credential used to obtain an access token; persisted encrypted in this implementation.','authentication'),('access token','A temporary provider credential prepared explicitly before the final send claim.','authentication'),('scope','A named permission in the Google consent grant, such as gmail.send.','authentication'),('entitlement','A present-tense decision about whether an owner may use a feature, based on policy and current state.','payments'),('idempotency','Repeated use of the same operation identity returns the same result or avoids repeating its effect.','sending'),('idempotency key','An owner-scoped UUID used to identify one campaign submission or checkout operation.','sending'),('snapshot','A stored copy of approved values, so later contact/template edits do not change a queued message.','database'),('MIME','The standard message format for text, HTML, headers and attachments; buildMime encodes it for Gmail.','sending'),('base64url','A URL-safe base64 encoding used for the raw Gmail MIME message.','sending'),('Message-ID','A stable message header identity; it is not proof of provider deduplication.','sending'),('outbox','Durable local intent committed before publication to an external work system.','architecture'),('inbox','A durable provider-event receipt stored before asynchronous processing.','payments'),('webhook','An HTTP callback from a provider. This app verifies Dodo signatures rather than requiring a user session.','payments'),('reconciliation','Comparing/rebuilding local evidence and provider observations, including repairing interrupted publication.','inngest'),('lease','A time-bounded claim on active work. Expiry does not prove the external effect did not happen.','sending'),('claim token','An unpredictable identity tying settlement to the exact claimed attempt.','sending'),('reservation','Durable accounting capacity assigned to a delivery before external submission.','database'),('UTC','Coordinated Universal Time, used for daily usage boundaries and documented cron schedules.','sending'),('half-open','A time range including its start and excluding its end, preventing overlap at boundaries.','payments'),('grace period','A verified extension of paid operational access that retains the same allowance identity.','payments'),('fail closed','Deny or defer protected work when required authorization/accounting controls are unavailable.','security-reliability'),('tenant','An owner whose data and operations must remain separate from other users.','database'),('row lock','A PostgreSQL transaction lock that serializes competing changes to the selected owner or budget.','database'),('transaction','A database unit whose local changes commit together or roll back together; external provider calls are outside it.','database'),('Prisma','The typed database client and schema/migration tooling used by this application.','database'),('App Router','The Next.js route organization used for layouts, pages, loading/error boundaries and handlers.','frontend'),('server action','A server-executed mutation entrypoint invoked by the UI; it still needs authentication and policy checks.','frontend'),('route handler','An HTTP endpoint implemented in an App Router route file.','function-reference'),('server component','A React component rendered on the server; it can prepare data without making all UI code client-side.','frontend'),('client component','A React component opting into browser interactivity with use client.','frontend'),('Inngest','The event/workflow orchestration library registering the app’s eight background functions.','inngest'),('durable step','An orchestration work boundary recorded by Inngest; replay semantics differ from another Gmail request.','inngest'),('cron','A schedule expression used by periodic maintenance registrations.','inngest'),('AES-256-GCM','Authenticated encryption used for refresh-token envelopes, with a random IV and integrity tag.','authentication'),('AAD','Additional authenticated data binding a v2 credential to its version, key ID, purpose and owner UUID.','authentication'),('IV','The random initialization value used by encryption; v2 uses 12 bytes.','authentication'),('compare-and-swap','Update only if an observed old value still matches, preserving concurrent reconnect/erasure changes.','authentication'),('tombstone','A retained deletion marker that blocks unsafe recreation or activation while cleanup is pending.','walkthrough-deletion'),('Standard Webhooks','The signature/timestamp verification protocol used on the exact raw Dodo request body.','payments'),('minor units','Integer currency subunits; configured examples include USD 599 and INR 29900.','payments'),('rollout guard','A configuration or persisted control preventing activation before readiness is established.','payments'),('rate limit','A request-frequency budget; separate from daily/monthly email allowance and Gmail provider limits.','security-reliability'),('UNCERTAIN','A delivery state where provider acceptance cannot be established; accounting remains and auto-resend is blocked.','sending'),('SetNull','A relation deletion behavior preserving the dependent record while clearing its foreign key.','database'),('Cascade','A relation deletion behavior removing dependent records, used for owner content but not every recovery record.','database'),('static export','Prebuilt HTML and assets served without an application server; used by this handbook.','cheat-sheet')]
glossary=[{'id':re.sub(r'[^a-z0-9]+','-',t.lower()).strip('-'),'term':t,'definition':d,'chapter':c} for t,d,c in defs]
(R/'content/glossary.json').write_text(json.dumps(glossary,indent=2))
